#!/usr/bin/env bash
set -euo pipefail

# VERSION 2 -- sustituye por completo a apply_auto_optimizacion_rutas.sh
# y a apply_fix_auto_optimizacion_json.sh (no hace falta ejecutar esos dos,
# de hecho NO los vuelvas a ejecutar: el primero todavia tiene el error de
# tipos ya corregido aqui, y volver a aplicarlo pisaria esta correccion).
#
# Motor de inteligencia (3/3, pieza final): auto-optimizacion de rutas, ya
# con el fix del error de build 'TS2322 ... InputJsonValue' incluido desde
# el principio (antes viajaba en un script aparte). Cuando una empresa
# activa 'autoAssignEnabled' (nueva pantalla Configuracion, APAGADO por
# defecto), cada vez que se genera la comparativa de transportistas en el
# Planificador (POST /optimization/:routeId/simulate) el sistema puntua
# los candidatos (coste, fiabilidad de distancia historica, ocupacion,
# anomalias recientes) y, si el mejor supera el umbral de confianza
# configurado con margen claro sobre el segundo, lo asigna solo --
# reutilizando exactamente la misma transaccion que ya usaba la seleccion
# manual. Nunca elige vehiculo ni conductor. Cambio de esquema aditivo (2
# columnas nuevas en Company, no destructivo) -- requiere
# 'npx prisma db push' (se hace solo, mas abajo; si ya lo aplicaste antes
# dira 'already in sync', es normal). Ejecutar desde la raiz del repo
# tms-production.

REPO_ROOT="$(pwd)"

mkdir -p "$REPO_ROOT/backend/prisma"
base64 -d > "$REPO_ROOT/backend/prisma/schema.prisma" <<'B64EOF'
