echo "OK: frontend/src/pages/planner/RouteAssignmentModal.tsx"

echo
echo "=== Actualizando cliente Prisma y esquema de base de datos ==="
(cd "$REPO_ROOT/backend" && npx prisma generate && npx prisma db push)
echo "=== Compilando backend ==="
(cd "$REPO_ROOT/backend" && npm run build)
echo "=== Compilando frontend (Backoffice) ==="
(cd "$REPO_ROOT/frontend" && npm run build)

echo
echo "Listo: auto-optimizacion de rutas (3/3, motor de inteligencia"
echo "completo), ya con el fix de tipos incluido. Apagada por defecto --"
echo "activarla en el menu Configuracion (solo admin_empresa/admin_plataforma)."
echo
echo "Si tienes el backend corriendo con \"npm run dev\", reinicialo para que"
echo "recoja los ficheros nuevos (Ctrl+C en su terminal y \"npm run dev\" otra vez)."
